assetHold.source:
let ASSETS_HELD = null;
const HELD_MEMO = new Map();
/* v7.75 - a save inside a hold makes the held list and memo stale; the next read rebuilds them once, so the rest of
   that draw shows the record as it now is. A draw with no save in it builds once, as before. */
let HELD_STALE775 = false;
function heldFresh775(){ if (ASSETS_HELD && HELD_STALE775) { HELD_STALE775 = false; HELD_MEMO.clear(); ASSETS_HELD = buildAllAssets(); } } /* the memo is emptied first, so the rebuilt list's own lookups (rentalOf) are fresh too */
function heldMemo(k, f){ if (!ASSETS_HELD) return f(); heldFresh775(); if (HELD_MEMO.has(k)) return HELD_MEMO.get(k); const v = f(); HELD_MEMO.set(k, v); return v; }

function allAssets(){ heldFresh775(); return ASSETS_HELD || buildAllAssets(); }
/* Run `fn` with the asset list built once. Nested calls keep the outer hold — one pass, one list. */
function holdAssets(fn){
if (ASSETS_HELD) { heldFresh775(); return fn(); }
 ASSETS_HELD = buildAllAssets(); HELD_MEMO.clear(); HELD_STALE775 = false;
 try { return fn(); } finally { ASSETS_HELD = null; HELD_MEMO.clear(); HELD_STALE775 = false; }
}

docketNoInName.source:
function docketNoInName(nm){
 const s = String(nm || ''); if (!s) return null;
 /* v5.81 — all three books: a hire agreement (red), a service note (green) or a collection form (blue) */
 const got = bookNumbers().find(n => { const no = String(n || '').trim();
 if (!/^\d{4,7}$/.test(no)) return false;
 if (allAssets().some(a => (a.asset_numbers || []).some(x => String(x).trim() === no))) return false;
 return new RegExp('(^|\\D)' + no + '(\\D|$)').test(s); });
 return got ? String(got).trim() : null;
}

applyRemote.source:
function applyRemote(name, snap){
 const docs = {}; snap.docs.forEach(d => { const b = d.data(); if (b) docs[d.id] = b; });
 if (!SYNC.first.has(name)) {
 SYNC.pending[name] = docs;
 if (Object.keys(SYNC.pending).length >= Object.keys(SYNC_COLLS).length) syncFirst();
 else if (!SYNC.ftimer) SYNC.ftimer = setTimeout(syncFirst, 6000);
 return;
 }
 if (syncFold(name, docs)) { persist(); syncRedraw(); }
}

syncFold.source:
function syncFold(name, docs){
 const c = SYNC_COLLS[name];
 const last = {}; Object.entries(docs).forEach(([id, b]) => last[id] = JSON.stringify(b));
 SYNC.last[name] = last;
 const shown = Object.assign({}, docs);
 if (!SYNC.readonly) Object.entries(SYNC.queue[name] || {}).forEach(([id, body]) => { if (body === null) delete shown[id]; else shown[id] = body; });
 const next = fromDocs(name, shown);
 if (JSON.stringify(next) === JSON.stringify(c.get())) return false;
 c.set(next);
 return true;
}

syncRedraw.source:
function syncRedraw(){
 clearTimeout(SYNC.rtimer);
 SYNC.rtimer = setTimeout(() => {
 const el = document.activeElement;
 const typing = el && /^(INPUT|TEXTAREA|SELECT)$/.test(el.tagName) && el.type !== 'button' && el.type !== 'date' && el.type !== 'time' && el.id !== 'q'
 && !(el.tagName === 'INPUT' && state.tab === 'change' && el.closest('#pane-change')); /* v7.02 - Change deliveries keeps the box across its redraw */
 if (typing) { SYNC.rtimer = setTimeout(syncRedraw, 1500); return; }
 try { render(); if (state.sel && document.querySelector('#drawer').classList.contains('on')) openAsset(state.sel, {keep: true}); } catch (e) {}
 syncFooter();
 }, 250);
}
